const { test } = require('node:test');
const assert = require('node:assert/strict');
const { parsePort } = require('../src/port.cjs');
test('valid port', () => assert.equal(parsePort('8080'), 8080));
test('rejects zero', () => assert.throws(() => parsePort('0'), RangeError));
test('rejects negative port', () => assert.throws(() => parsePort('-1'), RangeError));
test('rejects fractional port', () => assert.throws(() => parsePort('1.5'), RangeError));
test('rejects large port', () => assert.throws(() => parsePort('65536'), RangeError));

